def has_cycle_directed(graph):
    visiting = set()
    visited = set()
    nodes = set(graph)
    for neighbors in graph.values():
        nodes.update(neighbors)

    def visit(node):
        if node in visiting:
            return True
        if node in visited:
            return False
        visiting.add(node)
        for neighbor in graph.get(node, []):
            if visit(neighbor):
                return True
        visiting.remove(node)
        visited.add(node)
        return False

    return any(visit(node) for node in nodes)

